// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Collection, AccessorArrayLike } from '@stdlib/types/array';

/**
* Input array.
*/
type InputArray = Collection<unknown> | AccessorArrayLike<unknown>;

/**
* Output array.
*/
type OutputArray = Collection<number> | AccessorArrayLike<number>;

/**
* Insertion side.
*/
type Side = 'left' | 'right';

/**
* Interface describing `gsearchSorted`.
*/
interface Routine {
	/**
	* Finds the indices at which elements should be inserted into a sorted strided array in order to maintain sort order.
	*
	* ## Notes
	*
	* -   For each element in `x`, the function writes to `out` an index in the interval `[0, N]` such that inserting the element into `search` at that index preserves sort order.
	* -   If `side` is `'left'`, each index is the position of the first element in `search` which is greater than or equal to the search element (ascending order) or less than or equal to the search element (descending order).
	* -   If `side` is `'right'`, each index is the position of the first element in `search` which is strictly greater than the search element (ascending order) or strictly less than the search element (descending order).
	* -   If a search element is `NaN`, the function writes `-1` to the corresponding element in `out`.
	*
	* @param M - number of indexed elements in `x` and `out`
	* @param N - number of indexed elements in `search`
	* @param side - insertion side
	* @param x - input array containing search elements
	* @param strideX - stride length for `x`
	* @param search - sorted input array
	* @param strideSearch - stride length for `search`
	* @param out - output array
	* @param strideOut - stride length for `out`
	* @returns output array
	*
	* @example
	* var search = [ 1.0, 2.0, 2.0, 3.0 ];
	* var x = [ 0.0, 2.0, 4.0 ];
	* var out = [ 0, 0, 0 ];
	*
	* gsearchSorted( x.length, search.length, 'left', x, 1, search, 1, out, 1 );
	* // out => [ 0, 1, 4 ]
	*/
	<T extends OutputArray>( M: number, N: number, side: Side, x: InputArray, strideX: number, search: InputArray, strideSearch: number, out: T, strideOut: number ): T;

	/**
	* Finds the indices at which elements should be inserted into a sorted strided array in order to maintain sort order using alternative indexing semantics.
	*
	* ## Notes
	*
	* -   For each element in `x`, the function writes to `out` an index in the interval `[0, N]` such that inserting the element into `search` at that index preserves sort order.
	* -   If `side` is `'left'`, each index is the position of the first element in `search` which is greater than or equal to the search element (ascending order) or less than or equal to the search element (descending order).
	* -   If `side` is `'right'`, each index is the position of the first element in `search` which is strictly greater than the search element (ascending order) or strictly less than the search element (descending order).
	* -   If a search element is `NaN`, the function writes `-1` to the corresponding element in `out`.
	*
	* @param M - number of indexed elements in `x` and `out`
	* @param N - number of indexed elements in `search`
	* @param side - insertion side
	* @param x - input array containing search elements
	* @param strideX - stride length for `x`
	* @param offsetX - starting index for `x`
	* @param search - sorted input array
	* @param strideSearch - stride length for `search`
	* @param offsetSearch - starting index for `search`
	* @param out - output array
	* @param strideOut - stride length for `out`
	* @param offsetOut - starting index for `out`
	* @returns output array
	*
	* @example
	* var search = [ 1.0, 2.0, 2.0, 3.0 ];
	* var x = [ 0.0, 2.0, 4.0 ];
	* var out = [ 0, 0, 0 ];
	*
	* gsearchSorted.ndarray( x.length, search.length, 'right', x, 1, 0, search, 1, 0, out, 1, 0 );
	* // out => [ 0, 3, 4 ]
	*/
	ndarray<T extends OutputArray>( M: number, N: number, side: Side, x: InputArray, strideX: number, offsetX: number, search: InputArray, strideSearch: number, offsetSearch: number, out: T, strideOut: number, offsetOut: number ): T;
}

/**
* Finds the indices at which elements should be inserted into a sorted strided array in order to maintain sort order.
*
* ## Notes
*
* -   For each element in `x`, the function writes to `out` an index in the interval `[0, N]` such that inserting the element into `search` at that index preserves sort order.
* -   If `side` is `'left'`, each index is the position of the first element in `search` which is greater than or equal to the search element (ascending order) or less than or equal to the search element (descending order).
* -   If `side` is `'right'`, each index is the position of the first element in `search` which is strictly greater than the search element (ascending order) or strictly less than the search element (descending order).
* -   If a search element is `NaN`, the function writes `-1` to the corresponding element in `out`.
*
* @param M - number of indexed elements in `x` and `out`
* @param N - number of indexed elements in `search`
* @param side - insertion side
* @param x - input array containing search elements
* @param strideX - stride length for `x`
* @param search - sorted input array
* @param strideSearch - stride length for `search`
* @param out - output array
* @param strideOut - stride length for `out`
* @returns output array
*
* @example
* var search = [ 1.0, 2.0, 2.0, 3.0 ];
* var x = [ 0.0, 2.0, 4.0 ];
* var out = [ 0, 0, 0 ];
*
* gsearchSorted( x.length, search.length, 'left', x, 1, search, 1, out, 1 );
* // out => [ 0, 1, 4 ]
*
* @example
* var search = [ 1.0, 2.0, 2.0, 3.0 ];
* var x = [ 0.0, 2.0, 4.0 ];
* var out = [ 0, 0, 0 ];
*
* gsearchSorted.ndarray( x.length, search.length, 'right', x, 1, 0, search, 1, 0, out, 1, 0 );
* // out => [ 0, 3, 4 ]
*/
declare var gsearchSorted: Routine;


// EXPORTS //

export = gsearchSorted;
